package com.civsetu.media.storage;

import java.io.InputStream;

/**
 * Where uploaded file bytes live. Keys are generated by the server
 * (e.g. {@code issues/<issue-id>/<uuid>.jpg}), never taken from a user's file name.
 * Implementations are swapped by configuration: {@code civsetu.media.storage=local|s3}.
 */
public interface MediaStorage {

    void put(String key, byte[] content, String contentType);

    /** Opens the stored bytes; the caller closes the stream. */
    InputStream open(String key);

    /** Removes the object; does nothing if it does not exist. */
    void delete(String key);
}
